#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "2mm.hpp"

using num_t = DATA_TYPE;

namespace {

// convenient dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto l_vec = noarr::vector<'l'>();

// layout tuning: choose a concrete physical layout for each array
struct tuning {
	// tmp: i x j  (row-major: j inner, i outer)
	DEFINE_PROTO_STRUCT(tmp_layout, j_vec ^ i_vec);

	// A:   i x k  (row-major: k inner, i outer)
	//      ⇒ for a fixed i, A[i,k] is contiguous in k (good for k-reduction)
	DEFINE_PROTO_STRUCT(a_layout,  k_vec ^ i_vec);

	// B:   k x j
	//      Optimized layout: k inner, j outer
	//      ⇒ for a fixed j, B[k,j] is contiguous in k (good for inner k-loop)
	DEFINE_PROTO_STRUCT(b_layout,  k_vec ^ j_vec);

	// C:   j x l
	//      Optimized layout: j inner, l outer
	//      ⇒ for a fixed l, C[j,l] is contiguous in j (good for inner j-loop)
	DEFINE_PROTO_STRUCT(c_layout,  j_vec ^ l_vec);

	// D:   i x l  (row-major: l inner, i outer)
	DEFINE_PROTO_STRUCT(d_layout,  l_vec ^ i_vec);
} tuning;

// Array initialization.
//   A: ni x nk, index A[i][k]
//   B: nk x nj, index B[k][j]
//   C: nj x nl, index C[j][l]
//   D: ni x nl, index D[i][l]
void init_array(num_t &alpha, num_t &beta, auto A, auto B, auto C, auto D) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	const std::size_t ni = A | get_length<'i'>();
	const std::size_t nk = A | get_length<'k'>();
	const std::size_t nj = B | get_length<'j'>();
	const std::size_t nl = C | get_length<'l'>();

	// A[i][k] = ((i * k + 1) % ni) / ni
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % ni) / (num_t)ni;
	});

	// B[k][j] = (k * (j + 1) % nj) / nj
	traverser(B).for_each([=](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = (num_t)(k * (j + 1) % nj) / (num_t)nj;
	});

	// C[j][l] = ((j * (l + 3) + 1) % nl) / nl
	traverser(C).for_each([=](auto state) {
		auto [j, l] = get_indices<'j', 'l'>(state);
		C[state] = (num_t)((j * (l + 3) + 1) % nl) / (num_t)nl;
	});

	// D[i][l] = (i * (l + 2) % nk) / nk
	// note: uses nk as in the original C code
	traverser(D).for_each([=](auto state) {
		auto [i, l] = get_indices<'i', 'l'>(state);
		D[state] = (num_t)(i * (l + 2) % nk) / (num_t)nk;
	});
}

// Main computational kernel:
//   tmp  = alpha * A * B
//   D    = alpha * A * B * C + beta * D
// with shapes:
//   A:   i x k
//   B:   k x j
//   tmp: i x j
//   C:   j x l
//   D:   i x l
//
// Optimizations:
//   * Change B layout to be k-contiguous  ⇒ phase 1 has unit-stride in k for both A and B.
//   * Change C layout to be j-contiguous ⇒ phase 2 has unit-stride in j for both tmp and C.
//   * Apply cache blocking (tiling) in i,j,k,l using noarr::into_blocks_dynamic.
//   * Use per-output-element register accumulation so tmp[i,j] and D[i,l] are written once.
[[gnu::flatten, gnu::noinline]]
void kernel_2mm(num_t alpha, num_t beta, auto tmp, auto A, auto B, auto C, auto D) {
	using namespace noarr;

	// Tunable tile sizes; chosen conservatively but reasonably for modern CPUs.
	// They can be changed without affecting correctness.
	constexpr std::size_t tile_i = 32;
	constexpr std::size_t tile_j = 32;
	constexpr std::size_t tile_k = 32;
	constexpr std::size_t tile_l = 32;

#pragma scop
	// =====================================================================
	// PHASE 1: tmp = alpha * A * B
	//   tmp[i,j] = alpha * sum_k A[i,k] * B[k,j]
	//
	// We tile i, j, and k using into_blocks_dynamic:
	//   i -> (I block, i-in-block, presence 's')
	//   j -> (J block, j-in-block, presence 't')
	//   k -> (K block, k-in-block, presence 'u')
	//
	// For each (I,J) tile we:
	//   - for each (i,j) within that tile:
	//       acc = sum over all (K,k) of A[i,k] * B[k,j]
	//       tmp[i,j] = alpha * acc
	// This keeps the k-reduction local in registers and visits A and B with
	// k as the innermost varying index, matching their k-contiguous layouts.
	// =====================================================================
	auto phase1_trav = traverser(tmp, A, B).order(
		// split i into blocks I and intra-tile i, with guard 's'
		into_blocks_dynamic<'i', 'I', 'i', 's'>(tile_i)
		// split j into blocks J and intra-tile j, with guard 't'
		^ into_blocks_dynamic<'j', 'J', 'j', 't'>(tile_j)
		// split k into blocks K and intra-tile k, with guard 'u'
		^ into_blocks_dynamic<'k', 'K', 'k', 'u'>(tile_k)
	);

	phase1_trav.template for_dims<'I', 'J'>([&](auto trav_IJ) {
		// Here, tile indices I and J are fixed; we iterate over all i,j
		// within this (I,J) tile and compute one tmp[i,j] at a time.

		trav_IJ.template for_dims<'i', 's', 'j', 't'>([&](auto trav_ij) {
			// trav_ij has a concrete (i,j) (and also the guards 's','t').
			// Perform the k-reduction for this (i,j) pair.

			num_t acc = (num_t)0;

			// Iterate over all K-tiles and intra-tile k indices.
			// Guards 'u' ensure we skip padded elements in the last tile.
			trav_ij.template for_dims<'K', 'k', 'u'>([&](auto trav_ijk) {
				acc += A[trav_ijk] * B[trav_ijk];
			});

			// Apply alpha once per (i,j) and store the result.
			tmp[trav_ij] = alpha * acc;
		});
	});

	// =====================================================================
	// PHASE 2: D = beta * D + tmp * C
	//   D[i,l] = beta * D[i,l] + sum_j tmp[i,j] * C[j,l]
	//
	// We tile i, l, and j:
	//   i -> (I block, i-in-block, presence 's')
	//   l -> (L block, l-in-block, presence 'v')
	//   j -> (J block, j-in-block, presence 't')
	//
	// For each (I,L) tile we:
	//   - for each (i,l) in that tile:
	//       acc = beta * D[i,l]
	//       for all j: acc += tmp[i,j] * C[j,l]
	//       D[i,l] = acc
	//
	// This keeps D[i,l] in a register across the full j-reduction and
	// walks tmp and C with j as the innermost index, matching their j‑
	// contiguous layouts.
	// =====================================================================
	auto phase2_trav = traverser(D, tmp, C).order(
		// split i into blocks I and intra-tile i, with guard 's'
		into_blocks_dynamic<'i', 'I', 'i', 's'>(tile_i)
		// split l into blocks L and intra-tile l, with guard 'v'
		^ into_blocks_dynamic<'l', 'L', 'l', 'v'>(tile_l)
		// split j into blocks J and intra-tile j, with guard 't'
		^ into_blocks_dynamic<'j', 'J', 'j', 't'>(tile_j)
	);

	phase2_trav.template for_dims<'I', 'L'>([&](auto trav_IL) {
		// (I,L) tile fixed here.

		trav_IL.template for_dims<'i', 's', 'l', 'v'>([&](auto trav_il) {
			// trav_il identifies one logical element D[i,l] (with guards).

			// Start from beta * D[i,l] in a register.
			num_t acc = beta * D[trav_il];

			// Accumulate contributions over all j (blocked via J and j,t).
			trav_il.template for_dims<'J', 'j', 't'>([&](auto trav_ilj) {
				acc += tmp[trav_ilj] * C[trav_ilj];
			});

			// Write the final value once.
			D[trav_il] = acc;
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem sizes
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;

	// scalars
	num_t alpha;
	num_t beta;

	// set all potential lengths once; each layout will use the relevant ones
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl);

	// allocate bags with given layouts and lengths
	auto tmp = noarr::bag(noarr::scalar<num_t>() ^ tuning.tmp_layout ^ set_lengths);
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout   ^ set_lengths);
	auto B   = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout   ^ set_lengths);
	auto C   = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout   ^ set_lengths);
	auto D   = noarr::bag(noarr::scalar<num_t>() ^ tuning.d_layout   ^ set_lengths);

	// initialize arrays
	init_array(alpha, beta, A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	// measure execution time
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_2mm(alpha, beta, tmp.get_ref(), A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optionally dump the resulting D matrix (layout-agnostic)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' to be the outer dimension for row-wise printing
		noarr::serialize_data(std::cerr, D.get_ref() ^ noarr::hoist<'i'>());
	}

	// print elapsed time (seconds)
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
