	// Using moderate defaults that work reasonably well for typical
	// Polybench-like sizes and cache hierarchies.
	constexpr std::size_t tile_i = 32;
	constexpr std::size_t tile_j = 32;
	constexpr std::size_t tile_k = 32;
	constexpr std::size_t tile_l = 32;

	// We use into_blocks_dynamic for general NI/NJ/NK/NL. This splits each
	// logical dimension into:
	//   - a block index  (e.g. 'I' for 'i')
	//   - an intra-block index (re-using the original name, e.g. 'i')
	//   - a presence flag dimension ('s', 't', 'u', 'v') that is empty for
	//     out-of-range elements in the last, partial tile.
	//
	// The traverser created via .order(...) sees these additional dimensions
	// in for_dims<...>, but when we index the bags (tmp, A, B, C, D) with
	// the traverser, it is converted back to the original logical indices
	// (i, j, k, l), so the kernel remains layout-agnostic.

#pragma scop
