		.order(
			// block i, j, k
			noarr::into_blocks_dynamic<'i', 'I', 'i', 's'>(tile_i) ^
			noarr::into_blocks_dynamic<'j', 'J', 'j', 't'>(tile_j) ^
			noarr::into_blocks_dynamic<'k', 'K', 'k', 'u'>(tile_k)
		)
		// Outer tiles over i
		.template for_dims<'I'>([=](auto trav_I) {
			// Then tiles over j
			trav_I.template for_dims<'J'>([=](auto trav_IJ) {
				// 1) Zero tmp[i][j] for this (I,J) tile
				//    Dimensions:
				//      - 'i' : intra-tile row index
				//      - 's' : presence flag for i (handles partial tiles)
				//      - 'j' : intra-tile column index
				//      - 't' : presence flag for j
				trav_IJ.template for_dims<'i', 's', 'j', 't'>([=](auto trav_ij) {
					tmp[trav_ij] = (num_t)0;
				});

				// 2) Accumulate contributions from all k-tiles
				//    Loop order within tiles: i -> j -> k
				//    so that k is the innermost reduction dimension.
				trav_IJ.template for_dims<'K'>([=](auto trav_IJK) {
					trav_IJK.template for_dims<'i', 's', 'j', 't', 'k', 'u'>([=](auto trav) {
						// trav carries:
						//   I, i, s  (row tile and intra-row)
						//   J, j, t  (col tile and intra-col)
						//   K, k, u  (k-tile and intra-k plus presence)
						//
						// Due to our layouts:
						//   - A[i,k] is contiguous in k,
						//   - B[k,j] is contiguous in k (k inner in b_layout),
						// which makes this inner k-loop cache/SIMD-friendly.
						tmp[trav] += alpha * A[trav] * B[trav];
					});
				});
			});
		});

	// --------------------------------------------------------------------
	// PHASE 2: D[i][l] = beta * D[i][l] + sum_j tmp[i][j] * C[j][l]
	// --------------------------------------------------------------------
	traverser(D, tmp, C)
		.order(
			// block i, l, j
			noarr::into_blocks_dynamic<'i', 'I', 'i', 's'>(tile_i) ^
			noarr::into_blocks_dynamic<'l', 'L', 'l', 'v'>(tile_l) ^
			noarr::into_blocks_dynamic<'j', 'J', 'j', 't'>(tile_j)
		)
		// Outer tiles over i
		.template for_dims<'I'>([=](auto trav_I) {
			// Then tiles over l (columns of D)
			trav_I.template for_dims<'L'>([=](auto trav_IL) {
				// 1) Scale D[i][l] by beta once per element, before the
				//    reduction over j. This preserves the original arithmetic
				//    order (beta multiplication followed by j-sum).
				trav_IL.template for_dims<'i', 's', 'l', 'v'>([=](auto trav_il) {
					D[trav_il] *= beta;
				});

				// 2) Reduction over j, tiled by J. Within each (I,L,J) tile,
				//    the innermost dimension is j, which is contiguous in
				//    both tmp and C due to their layouts.
				trav_IL.template for_dims<'J'>([=](auto trav_ILJ) {
					trav_ILJ.template for_dims<'i', 's', 'l', 'v', 'j', 't'>([=](auto trav) {
						// Due to layouts:
						//   - tmp[i,j] is contiguous in j (j inner in tmp_layout),
						//   - C[j,l]   is contiguous in j (j inner in c_layout),
						// this j-innermost loop has good spatial locality and
						// can be vectorized by the compiler.
						D[trav] += tmp[trav] * C[trav];
					});
				});
			});
		});
#pragma endscop
