	constexpr auto TI = noarr::lit<32>;
	constexpr auto TJ = noarr::lit<32>;
	constexpr auto TK = noarr::lit<32>;
	constexpr auto TL = noarr::lit<32>;

#pragma scop
	// --------------------------------------------------------------------
	// Phase 1: tmp[i][j] = alpha * sum_k A[i][k] * B[k][j]
	// --------------------------------------------------------------------
	//
	// We tile i, j, k to keep blocks of A and B in cache and traverse k
	// innermost, where both A and B are contiguous:
	//   - A: layout k-inner,   so A[i,k] is contiguous in k
	//   - B: layout k-inner,   so B[k,j] is contiguous in k for fixed j
	//
	// The blocked structure has dimensions:
	//   I (tile over i), i (intra-tile), ri (guard)
	//   J (tile over j), j (intra-tile), rj (guard)
	//   K (tile over k), k (intra-tile), rk (guard)
	auto trav_phase1 = traverser(tmp, A, B).order(
		noarr::into_blocks_dynamic<'i', 'I', 'i', 'r'>(TI) ^
		noarr::into_blocks_dynamic<'j', 'J', 'j', 's'>(TJ) ^
		noarr::into_blocks_dynamic<'k', 'K', 'k', 't'>(TK)
	);

