	trav_phase1.template for_dims<'I', 'J'>([=](auto trav_IJ) {
		// 1) Initialize tmp(i,j) in this (I,J) tile to zero.
		//    We iterate only over valid i,j combinations via the guard
		//    dimensions 'r' and 's'.
		trav_IJ.template for_dims<'i', 'r', 'j', 's'>([=](auto trav_ij) {
			tmp[trav_ij] = (num_t)0;
		});

		// 2) Accumulate contributions from all K-tiles.
		trav_IJ.template for_dims<'K'>([=](auto trav_IJK) {
			// For fixed (I,J,K), iterate i, j, k within the tiles.
			// Order: i -> j -> k, with k innermost for unit-stride access.
			trav_IJK.template for_dims<'i', 'r', 'j', 's', 'k', 't'>([=](auto state) {
				// state carries (i,j,k) plus all tile indices and guards.
				// tmp does not depend on k, so multiple k-values map to the
				// same tmp[i,j] element and are accumulated here.
				tmp[state] += alpha * A[state] * B[state];
			});
		});
	});

	// --------------------------------------------------------------------
	// Phase 2: D[i][l] = beta * D[i][l] + sum_j tmp[i][j] * C[j][l]
	// --------------------------------------------------------------------
	//
	// We tile i, l, j to keep blocks of tmp, C, and D in cache.
	// Inner loop is over j, where both tmp and C are contiguous:
	//   - tmp: layout j-inner, so tmp[i,j] is contiguous in j
	//   - C:   layout j-inner, so C[j,l] is contiguous in j for fixed l
	//
	// The blocked structure has dimensions:
	//   I (tile over i), i (intra-tile), r  (guard for i)
	//   L (tile over l), l (intra-tile), u  (guard for l)
	//   J (tile over j), j (intra-tile), s  (guard for j)
	auto trav_phase2 = traverser(D, tmp, C).order(
		noarr::into_blocks_dynamic<'i', 'I', 'i', 'r'>(TI) ^
		noarr::into_blocks_dynamic<'l', 'L', 'l', 'u'>(TL) ^
		noarr::into_blocks_dynamic<'j', 'J', 'j', 's'>(TJ)
	);

	// Outer tile loops over (I, L)
	trav_phase2.template for_dims<'I', 'L'>([=](auto trav_IL) {
		// For each (i,l) pair in this (I,L) tile, we:
		//   acc = beta * D[i,l]
		//   acc += sum_{all j} tmp[i,j] * C[j,l]
		//   D[i,l] = acc
		trav_IL.template for_dims<'i', 'r', 'l', 'u'>([=](auto trav_il) {
			// Start from beta * D[i,l] in a register.
			num_t acc = beta * D[trav_il];

			// Sweep all j-tiles and within them all j-values.
			trav_il.template for_dims<'J'>([&](auto trav_ilJ) {
				trav_ilJ.template for_dims<'j', 's'>([&](auto trav_ilj) {
					acc += tmp[trav_ilj] * C[trav_ilj];
				});
			});

			// Write back once per (i,l).
			D[trav_il] = acc;
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem sizes
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;

	// scalars
	num_t alpha;
	num_t beta;

