	// B[k,j]: k is inner / contiguous (by tuned layout above)
	// => inner k-loop has unit-stride accesses in both A and B.
	// --------------------------------------------------------------------
	traverser(tmp, A, B).template for_dims<'i'>([=](auto trav_i) {
		// i is fixed here
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			// i and j are fixed here

			num_t acc = (num_t)0;

			// accumulate over k
			trav_ij.template for_dims<'k'>([&](auto trav_ijk) {
				// i, j, k fixed here
				acc += A[trav_ijk] * B[trav_ijk];
			});

			// apply alpha once per (i,j), not per (i,j,k)
			tmp[trav_ij] = alpha * acc;
		});
	});

